
/* ---- GRAFICA DI PROVA: sprite d'arte (WebP incorporati) al posto di quelli disegnati a codice ---- */
GfxNew.art=function(){
  // variants: [{f:specchia, fl:filtro}]
  const mkArt=(b64,lw,lh,ax,ay,vars)=>{
    const img=new Image(),out=vars.map(v=>{const[c,x]=mk(lw,lh);return{c,w:lw,h:lh,ax,ay,_x:x,art:1}});
    img.onload=()=>{out.forEach((s,i)=>{const x=s._x,v=vars[i];x.clearRect(0,0,lw,lh);
      x.save();if(v.f){x.translate(lw,0);x.scale(-1,1)}if(v.fl)x.filter=v.fl;x.drawImage(img,0,0,lw,lh);x.restore();
      const[c2,x2]=mk(lw,lh);x2.drawImage(s.c,0,0,lw,lh);x2.globalCompositeOperation='source-in';x2.fillStyle='#0e1c0a';x2.fillRect(0,0,lw,lh);s.sh=c2})};
    img.src='data:image/webp;base64,'+b64;return out;
  };
  const pal=mkArt("",151,165,69,164,[{},{f:1},{fl:'brightness(1.04) saturate(1.05)'}]);
  const palC=pal.map(s=>{const[c,x]=mk(151,165);return{c,w:151,h:165,ax:s.ax,ay:s.ay,_x:x,art:1}});
  const upd=()=>{palC.forEach((s,i)=>{s.sh=pal[i].sh;const x=s._x;x.clearRect(0,0,151,165);x.drawImage(pal[i].c,0,0,151,165);
    const mx=(i%2)?151-73.5:73.5;for(const[ox,oy]of[[-8,6],[6,9],[-1,16]]){ball(x,mx+ox,62+oy,5,'#b99a68','#6a4a26','#3a2612','rgba(30,18,8,.7)')}})};
  const t0=setInterval(upd,300);setTimeout(()=>clearInterval(t0),4000);
  SP.palm=palC;SP.palm0=pal;
  SP.tree=mkArt("",115,140,58,139,[{},{f:1},{fl:'brightness(.95) saturate(1.04)'},{f:1,fl:'brightness(1.05)'},{fl:'brightness(1.03) saturate(.94)'},{f:1,fl:'brightness(.93) saturate(1.06)'},{fl:'brightness(.97)'},{f:1,fl:'saturate(.96) brightness(1.02)'}]);
};
